// *** REQUEST SCOPE + SCOPED PROXY — one instance per HTTP request ***
// The proxy allows injection into singletons. Each method call delegates
// to the CURRENT request's RequestContext instance.
package com.bank.payment.context;

import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.annotation.Scope;
import org.springframework.context.annotation.ScopedProxyMode;
import org.springframework.stereotype.Component;
import org.springframework.web.context.WebApplicationContext;
import java.time.Instant;
import java.util.UUID;

@Component
@Scope(value = WebApplicationContext.SCOPE_REQUEST, proxyMode = ScopedProxyMode.TARGET_CLASS)
@Getter
@Setter
@Slf4j
public class RequestContext {

    private final String traceId;
    private final Instant startTime;
    private String userId;

    public RequestContext() {
        this.traceId = UUID.randomUUID().toString().substring(0, 8);
        this.startTime = Instant.now();
        log.debug("RequestContext created — traceId={} (one per HTTP request)", traceId);
    }

    public long getElapsedMs() {
        return Instant.now().toEpochMilli() - startTime.toEpochMilli();
    }
}
