// *** CORRECT: Uses ObjectProvider<PaymentTransaction> — fresh prototype per call ***
package com.bank.payment.service;

import com.bank.payment.context.RequestContext;
import com.bank.payment.dto.*;
import com.bank.payment.model.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class PaymentProcessingService {

    // ObjectProvider: factory for prototypes — getObject() returns FRESH instance every call
    private final ObjectProvider<PaymentTransaction> transactionProvider;

    // RequestContext: scoped proxy — each method call delegates to THIS request's instance
    private final RequestContext requestContext;  // actually a CGLIB proxy!

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        String traceId = requestContext.getTraceId(); // proxy → this request's context
        log.info("[{}] Processing payment: Rs.{} from {} to {} via {}",
            traceId, request.amount(), request.fromAccountId(),
            request.toAccountId(), request.method());

        // Get FRESH prototype — NOT the same instance as previous call!
        PaymentTransaction txn = transactionProvider.getObject();
        log.info("[{}] Created PaymentTransaction #{} (prototype — unique per call)",
            traceId, txn.getInstanceId());

        // Initialize with request data
        txn.initiate(request.fromAccountId(), request.toAccountId(),
            request.amount(), request.method());

        // Process (simplified — real app would call payment provider)
        txn.complete();

        log.info("[{}] Payment {} completed in {}ms",
            traceId, txn.getPaymentId(), requestContext.getElapsedMs());

        return new PaymentResponse(
            txn.getPaymentId(),
            txn.getFromAccountId(),
            txn.getToAccountId(),
            txn.getAmount(),
            txn.getMethod().name(),
            txn.getStatus(),
            traceId
        );
    }
}
