package com.bank.payment.service;

import com.bank.payment.context.RequestContext;
import com.bank.payment.dto.*;
import com.bank.payment.model.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.beans.factory.ObjectProvider;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class PaymentProcessingServiceTest {

    @Mock ObjectProvider<PaymentTransaction> transactionProvider;
    @Mock RequestContext requestContext;
    @InjectMocks PaymentProcessingService paymentService;

    @Test
    void shouldCreateFreshTransactionPerPayment() {
        // Each call to getObject() returns a DIFFERENT prototype instance
        PaymentTransaction txn1 = new PaymentTransaction();
        PaymentTransaction txn2 = new PaymentTransaction();
        when(transactionProvider.getObject()).thenReturn(txn1, txn2);
        when(requestContext.getTraceId()).thenReturn("test-trace");
        when(requestContext.getElapsedMs()).thenReturn(25L);

        // First payment
        PaymentResponse resp1 = paymentService.processPayment(
            new PaymentRequest("SAV2001", "CUR3001", new BigDecimal("5000"), PaymentMethod.UPI));

        // Second payment
        PaymentResponse resp2 = paymentService.processPayment(
            new PaymentRequest("CUR3001", "SAV2001", new BigDecimal("3000"), PaymentMethod.NEFT));

        // DIFFERENT payment IDs — proof that each call got a FRESH prototype
        assertThat(resp1.paymentId()).isNotEqualTo(resp2.paymentId());
        assertThat(resp1.method()).isEqualTo("UPI");
        assertThat(resp2.method()).isEqualTo("NEFT");

        // ObjectProvider.getObject() called TWICE — one per payment
        verify(transactionProvider, times(2)).getObject();
    }
}
